23	/// A wrapper of a state provider and a shared cache.
24	pub(crate) struct CachedStateProvider<S> {
25	    /// The state provider
26	    state_provider: S,
27	
28	    /// The caches used for the provider
29	    caches: ProviderCaches,
30	
31	    /// Metrics for the cached state provider
32	    metrics: CachedStateMetrics,
33	}
