35	impl<S> CachedStateProvider<S>
36	where
37	    S: StateProvider,
38	{
39	    /// Creates a new [`CachedStateProvider`] from a [`ProviderCaches`], state provider, and
40	    /// [`CachedStateMetrics`].
41	    pub(crate) const fn new_with_caches(
42	        state_provider: S,
43	        caches: ProviderCaches,
44	        metrics: CachedStateMetrics,
45	    ) -> Self {
