50	impl<S> CachedStateProvider<S> {
51	    /// Creates a new [`SavedCache`] from the given state updates, block hash, and account storage
52	    /// roots.
53	    ///
54	    /// This does not update the code cache, because no changes are required to the code cache on
55	    /// state change.
56	    ///
57	    /// NOTE: Consumers should ensure that these caches are not in use by a state provider for a
58	    /// previous block - otherwise, this update will cause that state provider to contain future
59	    /// state, which would be incorrect.
60	    pub(crate) fn save_cache(
61	        self,
62	        executed_block_hash: B256,
63	        state_updates: &BundleState,
64	    ) -> Result<SavedCache, PredicateError> {
65	        let Self { caches, metrics, state_provider: _ } = self;
66	        let start = Instant::now();
67	
68	        for (addr, account) in &state_updates.state {
69	            // If the account was not modified, as in not changed and not destroyed, then we have
70	            // nothing to do w.r.t. this particular account and can move on
71	            if account.status.is_not_modified() {
72	                continue
73	            }
74	
75	            // if the account was destroyed, invalidate from the account / storage caches
76	            if account.was_destroyed() {
77	                // invalidate the account cache entry if destroyed
78	                caches.account_cache.invalidate(addr);
79	
80	                // have to dereference here or else the closure moves the state update's lifetime
81	                // into the closure / out of the method body
82	                let addr = *addr;
83	
84	                // we also do not need to keep track of the returned PredicateId string
85	                caches
86	                    .storage_cache
87	                    .invalidate_entries_if(move |(account_addr, _), _| addr == *account_addr)?;
88	                continue
89	            }
90	
91	            // if we have an account that was modified, but it has a `None` account info, some wild
92	            // error has occurred because this state should be unrepresentable. An account with
93	            // `None` current info, should be destroyed.
94	            let Some(ref account_info) = account.info else {
95	                todo!("error handling - a modified account has None info")
96	            };
97	
98	            // insert will update if present, so we just use the new account info as the new value
99	            // for the account cache
100	            caches.account_cache.insert(*addr, Some(Account::from(account_info)));
101	
102	            // now we iterate over all storage and make updates to the cached storage values
103	            for (storage_key, slot) in &account.storage {
104	                // we convert the storage key from U256 to B256 because that is how it's represented
105	                // in the cache
106	                caches
107	                    .storage_cache
108	                    .insert((*addr, (*storage_key).into()), Some(slot.present_value));
109	            }
110	        }
111	
112	        // run pending tasks on all caches
113	        caches.storage_cache.run_pending_tasks();
114	        caches.account_cache.run_pending_tasks();
115	        caches.code_cache.run_pending_tasks();
116	
117	        // set metrics
118	        metrics.storage_cache_size.set(caches.storage_cache.entry_count() as f64);
119	        metrics.account_cache_size.set(caches.account_cache.entry_count() as f64);
120	        metrics.code_cache_size.set(caches.code_cache.entry_count() as f64);
121	
122	        tracing::debug!(target: "engine::caching", update_latency=?start.elapsed(), "Updated state caches");
123	
124	        // create a saved cache with the executed block hash, same metrics, and updated caches
125	        let saved_cache = SavedCache { hash: executed_block_hash, caches, metrics };
126	
127	        Ok(saved_cache)
128	    }
129	}
