172	impl CachedStateMetrics {
173	    /// Sets all values to zero, indicating that a new block is being executed.
174	    pub(crate) fn reset(&self) {
175	        // code cache
176	        self.code_cache_hits.set(0);
177	        self.code_cache_misses.set(0);
178	
179	        // storage cache
180	        self.storage_cache_hits.set(0);
181	        self.storage_cache_misses.set(0);
182	
183	        // account cache
184	        self.account_cache_hits.set(0);
185	        self.account_cache_misses.set(0);
186	    }
187	
188	    /// Returns a new zeroed-out instance of [`CachedStateMetrics`].
189	    pub(crate) fn zeroed() -> Self {
190	        let zeroed = Self::default();
191	        zeroed.reset();
192	        zeroed
193	    }
194	}
